import{at as e,it as t,n,vt as r}from"./chunks/framework.BVWCHfG0.js";var i=JSON.parse(`{"title":"Performing releases","description":"","frontmatter":{},"headers":[],"relativePath":"maintainer-guide/releases.md","filePath":"docs/maintainer-guide/releases.md","lastUpdated":1790710395000}`),a={name:`maintainer-guide/releases.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="performing-releases" tabindex="-1">Performing releases <a class="header-anchor" href="#performing-releases" aria-label="Permalink to “Performing releases”">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Releasing a\xA0new version makes sense only when\xA0there are changes that\xA0are significant for\xA0users. Therefore, the\xA0<strong>Unreleased</strong> section of\xA0the\xA0<a href="https://stylelint-stylistic.github.io/changelog" target="_blank" rel="noreferrer">CHANGELOG.md</a> in\xA0the\xA0<code>main</code> branch should not\xA0be empty.</p></div><p>To\xA0release a\xA0new version:</p><ol><li><p>Create a\xA0pull request from\xA0the\xA0<code>main</code> branch to\xA0the\xA0<code>release</code> branch.</p></li><li><p>After\xA0agreement with\xA0the\xA0other team members, <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/incorporating-changes-from-a-pull-request/about-pull-request-merges#rebase-and-merge-your-commits" target="_blank" rel="noreferrer">“Rebase and\xA0merge”</a> this pull request. This will trigger the\xA0GitHub Action for\xA0the\xA0release.</p></li><li><p>Wait for\xA0the\xA0successful completion of\xA0the\xA0action. Success means that:</p><ul><li>In\xA0the\xA0new commit (with\xA0the\xA0new version number in\xA0the\xA0title), the\xA0package version in\xA0<code>package.json</code> and\xA0<code>CHANGELOG.md</code> has been updated.</li><li>This commit has a\xA0tag with\xA0the\xA0version number, and\xA0the\xA0<code>main</code> and\xA0<code>release</code> branches have been updated.</li><li>Release notes for\xA0the\xA0new version have appeared in\xA0the\xA0<a href="https://github.com/stylelint-stylistic/stylelint-stylistic/releases" target="_blank" rel="noreferrer">Releases</a>.</li><li>The\xA0new version of\xA0the\xA0package has been published on\xA0<a href="https://www.npmjs.com/package/@stylistic/stylelint-plugin" target="_blank" rel="noreferrer">npmjs.org</a>.</li><li>The\xA0documentation site has been published from\xA0the\xA0new version.</li></ul></li><li><p>If\xA0the\xA0automation fails, check the\xA0<a href="https://github.com/stylelint-stylistic/stylelint-stylistic/actions/workflows/release.yaml" target="_blank" rel="noreferrer">GitHub Actions logs</a> for\xA0troubleshooting.</p></li></ol><p>If\xA0necessary, release <a href="https://github.com/stylelint-stylistic/stylelint-config/" target="_blank" rel="noreferrer"><code>@stylistic/stylelint-config</code></a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The\xA0release level is determined automatically based on\xA0the\xA0presence of\xA0certain subsections in\xA0the\xA0<strong>Unreleased</strong> section of\xA0the\xA0changelog:</p><ul><li>If\xA0there is <strong>“Changed”</strong> (with\xA0breaking changes)\xA0— it is always <em>major</em>, regardless of\xA0the\xA0presence of\xA0“Added” and\xA0“Fixed”.</li><li>If\xA0there is <strong>“Added”</strong> (with\xA0new features)\xA0— it is <em>minor</em>, regardless of\xA0the\xA0presence of\xA0“Fixed”.</li><li>If\xA0there is only <strong>“Fixed”</strong> (with\xA0bug fixes)\xA0— it is <em>patch</em>.</li></ul></div><h2 id="prereleases" tabindex="-1">Prereleases <a class="header-anchor" href="#prereleases" aria-label="Permalink to “Prereleases”">​</a></h2><p>A\xA0branch named <code>release-&lt;suffix&gt;</code> publishes a\xA0prerelease instead, e.g. <code>release-rc</code> publishes release candidates, <code>6.0.0-rc.&lt;n&gt;</code>. The\xA0package goes to\xA0npm under\xA0the\xA0dist-tag named by\xA0the\xA0suffix, <code>rc</code>, so\xA0<code>npm add @stylistic/stylelint-plugin</code> keeps installing the\xA0latest stable version.</p><h2 id="publishing-the-documentation" tabindex="-1">Publishing the\xA0documentation <a class="header-anchor" href="#publishing-the-documentation" aria-label="Permalink to “Publishing the\xA0documentation”">​</a></h2><p>A\xA0release publishes the\xA0site by\xA0itself. Between\xA0releases, a\xA0correction of\xA0the\xA0documentation reaches the\xA0site through\xA0the\xA0<code>deploy-docs</code> branch: open a\xA0pull request from\xA0<code>main</code> to\xA0it and\xA0merge it, and\xA0the\xA0<a href="https://github.com/stylelint-stylistic/stylelint-stylistic/actions/workflows/docs.yaml" target="_blank" rel="noreferrer">Docs workflow</a> builds the\xA0site from\xA0the\xA0branch and\xA0publishes it. The\xA0workflow can also be started by\xA0hand from\xA0the\xA0Actions tab.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};